import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../app/app_state.dart';
import '../models/contract.dart';
import '../theme/app_theme.dart';
import '../app/formatters.dart';
class ContractsScreen extends StatefulWidget{const ContractsScreen({super.key});@override State<ContractsScreen> createState()=>_ContractsScreenState();}
class _ContractsScreenState extends State<ContractsScreen>{int tab=0;String q='';@override Widget build(BuildContext context){final s=context.watch<AppState>();final all=s.contracts;final lists=[all.where((e)=>e.status==ContractStatus.available).toList(),all.where((e)=>e.status==ContractStatus.inTransit).toList(),all.where((e)=>e.status==ContractStatus.completed||e.status==ContractStatus.failed).toList(),<CargoContract>[]];final shown=lists[tab].where((e)=>(e.originCityName+e.destinationCityName+e.cargoType.name).toLowerCase().contains(q.toLowerCase())).toList();return ListView(padding:const EdgeInsets.all(13),children:[Row(children:List.generate(4,(i)=>Expanded(child:Padding(padding:const EdgeInsets.only(right:4),child:ChoiceChip(label:Text(['Tersedia','Aktif','Riwayat','Barang pemain'][i]+' • '+lists[i].length.toString(),style:const TextStyle(fontSize:9)),selected:tab==i,onSelected:(_)=>setState(()=>tab=i))))),const SizedBox(height:12),Row(children:[Expanded(child:TextField(onChanged:(v)=>setState(()=>q=v),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Cari rute atau muatan'))),const SizedBox(width:7),OutlinedButton(onPressed:()=>showModalBottomSheet(context:context,builder:(_)=>const Padding(padding:EdgeInsets.all(20),child:Text('Filter kontrak: rute, muatan, dan reward.'))),child:const Text('Filter'))]),const SizedBox(height:12),if(shown.isEmpty)const Center(child:Padding(padding:EdgeInsets.all(35),child:Column(children:[Icon(Icons.assignment_outlined,size:44,color:AppColors.textSecondary),Text('Belum ada kontrak di kategori ini',style:TextStyle(color:AppColors.textSecondary))])))else ...shown.map((c)=>Container(margin:const EdgeInsets.only(bottom:10),padding:const EdgeInsets.all(13),decoration:BoxDecoration(color:AppColors.surface,borderRadius:BorderRadius.circular(15),border:Border.all(color:AppColors.border)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(c.cargoType.name.toUpperCase(),style:const TextStyle(color:AppColors.emerald,fontWeight:FontWeight.w900,fontSize:10))),Text(c.distanceKm.toStringAsFixed(0)+' km',style:const TextStyle(color:AppColors.textSecondary))]),const SizedBox(height:9),Row(children:[Expanded(child:Text(c.originCityName,style:const TextStyle(fontWeight:FontWeight.w900))),const Icon(Icons.arrow_forward,color:AppColors.emerald),Expanded(child:Text(c.destinationCityName,textAlign:TextAlign.end,style:const TextStyle(fontWeight:FontWeight.w900)))]),Text(c.cargoWeightKg.toStringAsFixed(0)+' kg • '+c.rewardXp.toString()+' XP',style:const TextStyle(color:AppColors.textSecondary,fontSize:10)),const Divider(),Row(children:[Expanded(child:Text(GameFormatters.currency(c.reward),style:const TextStyle(color:AppColors.emerald,fontWeight:FontWeight.w900,fontSize:16))),if(tab==0)FilledButton(onPressed:()=>_dispatch(context,s,c.contractId),child:const Text('Pilih kendaraan'))])])))]); }Future<void> _dispatch(BuildContext context,AppState s,String id)async{final options=s.vehicles.where((v)=>v.canDrive).toList();if(options.isEmpty){s.showToast('Tidak ada kendaraan yang siap berangkat.');return;}showModalBottomSheet(context:context,builder:(ctx)=>SafeArea(child:Column(mainAxisSize:MainAxisSize.min,children:options.map((v)=>ListTile(title:Text(v.specifications.name),subtitle:Text(v.fuel.toStringAsFixed(0)+' L BBM'),onTap:()async{Navigator.pop(ctx);try{await s.dispatchContract(contractId:id,vehicleId:v.vehicleId);}catch(e){s.showToast(e.toString());}})).toList())));}}